    # Find rectangular periodic template motifs. Repeated motifs in one area
    # indicate that the contrasting right-hand block should be filled.
    counts = {}
    for row in grid:
        for x in row: counts[x] = counts.get(x, 0) + 1
    bg = max(counts, key=counts.get)
    # Identify rows forming a non-background stripe, fill its remainder with 1.
    for r, row in enumerate(grid):
        non = [c for c,v in enumerate(row) if v != bg]
        if non and non == list(range(min(non), max(non)+1)):
            # transform incomplete solid band: color its remaining background
