            if min(non) == 0 and max(non) < w-1:
                for c in range(max(non)+1, w):
                    # only mark the one-cell continuation marker
                    break
                out[r][max(non)] = 1
            elif max(non) == w-1 and min(non) > 0:
                out[r][min(non)] = 1
